function loadDB(){try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved)return {...structuredClone(seed),...saved,settings:{...seed.settings,...saved.settings}}}catch(e){}return structuredClone(seed)}function save(){localStorage.setItem(KEY,JSON.stringify(db))}function initials(s=''){return s.split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase()}function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function day(s){return new Date(s+'T12:00:00').toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}function toast(s){const t=document.getElementById('toast');t.textContent=s;t.classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}function setLanguage(v){localStorage.setItem('mwa_lang',v);const landingLanguage=document.getElementById('languageSelect');if(landingLanguage)landingLanguage.value=v;document.documentElement.lang=v;document.querySelectorAll('[data-i18n]').forEach(e=>{const str=(I18N[v]||I18N.en)[e.dataset.i18n];if(str){if(e.dataset.i18n==='heroTitle'&&v==='en')e.innerHTML='Your future starts <em>here.</em>';else e.textContent=str}});window.applyPortalLanguage?.()}
