const slides=[{image:'https://images.unsplash.com/photo-1509062522246-3755977927d7?auto=format&fit=crop&w=1400&q=85',kicker:'LEARN BY DOING',title:'Curiosity opens doors.',text:'Explore a campus where every question matters.'},{image:'https://images.unsplash.com/photo-1523240795612-9a054b0db644?auto=format&fit=crop&w=1400&q=85',kicker:'GROW TOGETHER',title:'Find your people.',text:'Build friendships and confidence that last.'},{image:'https://images.unsplash.com/photo-1523580494863-6f3031224c94?auto=format&fit=crop&w=1400&q=85',kicker:'MAKE YOUR MARK',title:'Imagine what comes next.',text:'Discover the skills to shape your own future.'}];
function setSlide(n){slide=(n+slides.length)%slides.length;const s=slides[slide];document.getElementById('heroPhoto').style.backgroundImage=`url("${s.image}")`;document.getElementById('slideKicker').textContent=s.kicker;document.getElementById('slideTitle').textContent=s.title;document.getElementById('slideText').textContent=s.text;document.getElementById('slideNumber').textContent='0'+(slide+1);document.querySelectorAll('.slide-dots button').forEach((b,i)=>b.classList.toggle('selected',i===slide))}
document.getElementById('slideDots').innerHTML=slides.map((_,i)=>`<button aria-label="Slide ${i+1}" onclick="setSlide(${i})"></button>`).join('');setSlide(0);setInterval(()=>setSlide(slide+1),6500);document.getElementById('nextSlide').onclick=()=>setSlide(slide+1);document.getElementById('prevSlide').onclick=()=>setSlide(slide-1);document.getElementById('yearNow').textContent=new Date().getFullYear();
function authTab(t){const reg=t==='register';document.getElementById('registerPane').hidden=!reg;document.getElementById('loginPane').hidden=reg;document.getElementById('registerTab').classList.toggle('selected',reg);document.getElementById('loginTab').classList.toggle('selected',!reg)}document.getElementById('loginTab').onclick=()=>authTab('login');document.getElementById('registerTab').onclick=()=>authTab('register');document.getElementById('demoFill').onclick=()=>{document.getElementById('loginEmail').value='admin@school.edu';document.getElementById('loginPassword').value='school123'};document.getElementById('languageSelect').onchange=e=>setLanguage(e.target.value);document.getElementById('mobileNav').onclick=()=>document.querySelector('.site-nav').classList.toggle('open');
document.getElementById('loginForm').onsubmit=e=>{e.preventDefault();const email=document.getElementById('loginEmail').value.trim().toLowerCase(),pass=document.getElementById('loginPassword').value;const u=db.users.find(x=>x.email.toLowerCase()===email&&x.password===pass);if(!u){toast('Email or password is not correct. Try a demo login.');return}if(u.status==='Pending'){toast('Your enrollment request is waiting for registrar approval.');return}current=u;enterPortal()};
document.getElementById('registerForm').onsubmit=e=>{e.preventDefault();if(!db.settings.registrationOpen){toast('Student registration is currently closed.');return}const f=new FormData(e.currentTarget),email=String(f.get('email')).trim().toLowerCase();if(db.users.some(u=>u.email.toLowerCase()===email)){toast('This email already has an account or request.');return}const name=String(f.get('name')).trim();const u={name,email,password:f.get('password'),role:'student',status:'Pending',id:'MWA-'+(2600+db.users.filter(x=>x.role==='student').length+1),grade:f.get('grade'),guardian:f.get('guardian'),phone:f.get('phone')||'—',room:'Pending',dob:'',address:'',emergency:f.get('guardian')+' · '+(f.get('phone')||'—')};db.users.push(u);db.payments.push({student:name,id:u.id,description:'Academic year registration',amount:450,status:'Pending',date:new Date().toISOString().slice(0,10),method:'Awaiting payment'});save();e.currentTarget.reset();toast('Request submitted. A registrar must approve it before portal access.');authTab('login')};document.getElementById('forgotLink').onclick=e=>{e.preventDefault();toast('Please contact the school office to reset your password.')};
const navigation={admin:[['Overview','overview','▦'],['Students & enrollment','students','♙'],['Staff directory','staff','♟'],['Classes & timetable','classes','▤'],['Attendance','attendance','◷'],['Grades & transcripts','grades','✳'],['Online exams','exams','◉'],['Fees & payments','finance','＄'],['Announcements','announcements','▣'],['Complaints','complaints','✉'],['Transfer requests','transfers','⇄'],['School settings','settings','⚙']],registrar:[['Overview','overview','▦'],['Students & enrollment','students','♙'],['Classes & timetable','classes','▤'],['Attendance','attendance','◷'],['Grades & transcripts','grades','✳'],['Fees & payments','finance','＄'],['Announcements','announcements','▣'],['Complaints','complaints','✉'],['Transfer requests','transfers','⇄']],teacher:[['Overview','overview','▦'],['My classes','classes','▤'],['Class roster','roster','♙'],['Attendance','attendance','◷'],['Grades','grades','✳'],['Online exams','exams','◉'],['Announcements','announcements','▣'],['Complaints','complaints','✉']],student:[['My dashboard','overview','▦'],['My profile','profile','♙'],['My class','classes','▤'],['My grades','grades','✳'],['Online exams','exams','◉'],['Fees & payments','finance','＄'],['Announcements','announcements','▣'],['Complaints','complaints','✉'],['Transfer requests','transfers','⇄']]};const roleName={admin:'Administrator',registrar:'Registrar',teacher:'Teacher',student:'Student'};
function enterPortal(){document.getElementById('landing').hidden=true;document.getElementById('portal').hidden=false;document.getElementById('userName').textContent=current.name;document.getElementById('userRole').textContent=roleName[current.role];document.getElementById('userInitials').textContent=initials(current.name);document.getElementById('topAvatar').textContent=initials(current.name);document.getElementById('roleLabel').textContent=roleName[current.role].toUpperCase()+' PORTAL';document.getElementById('sideNav').innerHTML=navigation[current.role].map(([n,id,ico])=>`<button data-page="${id}" class="${id==='overview'?'active':''}"><span class="nav-ico">${ico}</span>${n}</button>`).join('');document.getElementById('sideNav').onclick=e=>{const b=e.target.closest('[data-page]');if(b)showPage(b.dataset.page)};document.getElementById('userMenu').onclick=logout;document.getElementById('topAvatar').onclick=logout;document.getElementById('sidebarToggle').onclick=()=>document.getElementById('sidebar').classList.toggle('open');document.getElementById('portalBell').onclick=()=>toast('You’re all caught up!');document.getElementById('chatLaunch').onclick=toggleChat;document.getElementById('chatClose').onclick=toggleChat;document.getElementById('chatForm').onsubmit=sendChat;renderChat();setLanguage(localStorage.getItem('mwa_lang')||'en');showPage('overview')}
function logout(){current=null;clearInterval(examInterval);document.getElementById('portal').hidden=true;document.getElementById('landing').hidden=false;document.getElementById('sidebar').classList.remove('open');authTab('login')}
function showPage(p){currentPage=p;document.querySelectorAll('#sideNav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));document.getElementById('pageCrumb').textContent=({overview:'Overview',students:'Students & enrollment',staff:'Staff directory',classes:'Classes & timetable',roster:'Class roster',attendance:'Attendance',grades:'Grades & transcripts',exams:'Online exams',finance:'Fees & payments',announcements:'Announcements',settings:'School settings',profile:'My profile',complaints:'Complaints',transfers:'Transfer requests'})[p]||p;document.getElementById('sidebar').classList.remove('open');const c=document.getElementById('portalContent');({overview:renderOverview,students:renderStudents,staff:renderStaff,classes:renderClasses,roster:renderRoster,attendance:renderAttendance,grades:renderGrades,exams:renderExams,finance:window.renderFinance||renderFinance,announcements:renderAnnouncements,complaints:window.renderComplaints,transfers:window.renderTransfers,settings:renderSettings,profile:renderProfile}[p]||renderOverview)(c);window.applyPortalLanguage?.()}
function heading(title,sub,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}function action(label,onclick,light=false){return `<button class="${light?'button-light':'button-sm'}" onclick="${onclick}">${label}</button>`}function students(){return db.users.filter(u=>u.role==='student')}function titleFor(){return current.role==='student'?`Welcome back, ${esc(current.name.split(' ')[0])} 👋`:`Good morning, ${esc(current.name.split(' ')[0])} 👋`}
function renderOverview(c){const people=students(),pending=people.filter(s=>s.status==='Pending').length;let s;if(current.role==='student'){const my=db.grades.filter(g=>g.student===current.name),avg=my.length?Math.round(my.reduce((a,b)=>a+b.score,0)/my.length):0,paid=db.payments.filter(p=>p.studentAuthId===current.authId&&p.status==='Paid').length;s=`${heading(titleFor(),'Your learning, schedule, and school updates in one place.')}<div class="grid stats"><div class="card stat"><div class="stat-top">My class <span class="stat-icon">♙</span></div><div class="stat-num" style="font-size:17px">${esc(current.grade||'Grade 10')}</div><div class="stat-foot">${esc(current.room||'Room 204')} · Semester 1</div></div><div class="card stat"><div class="stat-top">Grade average <span class="stat-icon">✳</span></div><div class="stat-num">${avg||'—'}%</div><div class="stat-foot">From ${my.length} recorded subjects</div></div><div class="card stat"><div class="stat-top">Upcoming exams <span class="stat-icon">◉</span></div><div class="stat-num">${availableExams().length}</div><div class="stat-foot">Available for your class</div></div><div class="card stat"><div class="stat-top">Registration payment <span class="stat-icon">＄</span></div><div class="stat-num" style="font-size:17px">${paid?'Paid':'Pending'}</div><div class="stat-foot">Academic year 2026–2027</div></div></div><div class="grid dash-grid"><div class="card"><div class="card-head"><div><h2>My academic progress</h2><p>Assessment scores this semester</p></div>${action('View grades →',"showPage('grades')",true)}</div>${progressChart(my)}</div><div class="card"><div class="card-head"><div><h2>Next up</h2><p>School calendar and exams</p></div></div>${availableExams().length?availableExams().slice(0,2).map(examMini).join(''):'<div class="empty">No exams are open right now.</div>'}</div></div><div class="grid split"><div class="card table-card"><div class="table-toolbar"><h2>My recent grades</h2><a onclick="showPage('grades')">All results →</a></div>${gradeTable(my.slice(-5).reverse())}</div><div class="card"><div class="table-toolbar"><h2>School announcements</h2><a onclick="showPage('announcements')">View all →</a></div>${noticesMini()}</div></div>`}
else{s=`${heading(titleFor(),'Here’s what is happening across the school today.',current.role==='admin'?action('＋ Add student',"openRecord('student')"):current.role==='teacher'?action('＋ Create exam',"openRecord('exam')"):'')}<div class="grid stats"><div class="card stat"><div class="stat-top">Enrolled students <span class="stat-icon">♙</span></div><div class="stat-num">${people.filter(p=>p.role==='student'&&p.status==='Active').length.toLocaleString()}</div><div class="stat-foot"><span class="up">${people.filter(x=>x.status==='Active').length} active</span> · ${pending} awaiting review</div></div><div class="card stat"><div class="stat-top">Present today <span class="stat-icon">✓</span></div><div class="stat-num">1,119</div><div class="stat-foot"><span class="up">87.1%</span> school attendance</div></div><div class="card stat"><div class="stat-top">Fees collected <span class="stat-icon">＄</span></div><div class="stat-num">$${db.payments.filter(p=>p.status==='Paid').reduce((a,p)=>a+Number(p.amount),0).toLocaleString()}</div><div class="stat-foot">${db.payments.filter(p=>p.status==='Pending').length} payments awaiting confirmation</div></div><div class="card stat"><div class="stat-top">Needs attention <span class="stat-icon">!</span></div><div class="stat-num">${pending+db.payments.filter(p=>p.status==='Pending').length}</div><div class="stat-foot">Enrollment requests and payments</div></div></div><div class="grid dash-grid"><div class="card"><div class="card-head"><div><h2>School overview</h2><p>Enrollment and academic progress snapshot</p></div><span class="status green">2026–2027 · Semester 1</span></div>${progressChart(db.grades.filter(g=>current.role!=='teacher'||db.classes.some(x=>x.teacher===current.name&&x.grade===g.grade)))}</div><div class="card"><div class="card-head"><div><h2>Attendance today</h2><p>School-wide summary</p></div>${action('Open attendance →',"showPage('attendance')",true)}</div><div class="ring-row"><div class="ring"><span>87%</span></div><div class="ring-copy"><b>Good attendance today</b><small>1,119 students present<br>165 students absent</small></div></div><div class="key-row"><span>Attendance submitted</span><b>28 / 30 classes</b></div><div class="key-row"><span>School average</span><b>88.4%</b></div></div></div><div class="grid split"><div class="card table-card"><div class="table-toolbar"><h2>${current.role==='teacher'?'My students':'Recent student records'}</h2><a onclick="showPage('${current.role==='teacher'?'roster':'students'}')">View directory →</a></div>${studentTable(people.slice(0,5))}</div><div class="card"><div class="table-toolbar"><h2>Latest activity</h2><a onclick="showPage('announcements')">Announcements →</a></div>${noticesMini()}</div></div>`}c.innerHTML=s}
function progressChart(grades){const subjects=db.subjects.slice(0,6),values=subjects.map(x=>{const a=grades.filter(g=>g.subject===x);return a.length?Math.round(a.reduce((t,g)=>t+g.score,0)/a.length):Math.floor(64+Math.random()*20)});return `<div class="chart"><svg viewBox="0 0 640 170" preserveAspectRatio="none"><defs><linearGradient id="fade" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#6f9c79" stop-opacity=".2"/><stop offset="1" stop-color="#6f9c79" stop-opacity="0"/></linearGradient></defs>${[22,58,94,130].map(y=>`<line class="gridline" x1="35" y1="${y}" x2="635" y2="${y}"/>`).join('')}<path class="area" d="M${values.map((v,i)=>`${45+i*115} ${136-(v-50)*1.9}`).join(' L')} L620 150 L45 150 Z"/><path class="line" d="M${values.map((v,i)=>`${45+i*115} ${136-(v-50)*1.9}`).join(' L')}"/>${subjects.map((n,i)=>`<text class="axis" x="${35+i*115}" y="165">${esc(n.slice(0,9))}</text>`).join('')}</svg></div>`}
function studentTable(list){return `<div class="table-wrap"><table><thead><tr><th>STUDENT</th><th>ID</th><th>GRADE</th><th>STATUS</th></tr></thead><tbody>${list.map(u=>`<tr><td class="name"><div class="student-cell"><span class="mini-avatar">${initials(u.name)}</span>${esc(u.name)}</div></td><td>${esc(u.id)}</td><td>${esc(u.grade)}</td><td>${badge(u.status)}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">No student records yet.</td></tr>'}</tbody></table></div>`}function badge(s){return `<span class="status ${s==='Active'||s==='Paid'||s==='Approved'?'green':s==='Pending'?'amber':'red'}">${esc(s||'—')}</span>`}function gradeTable(list){return `<div class="table-wrap"><table><thead><tr><th>SUBJECT</th><th>ASSESSMENT</th><th>TYPE</th><th>TERM</th><th>SCORE</th><th>LETTER</th></tr></thead><tbody>${list.map(g=>`<tr><td class="name">${esc(g.subject)}</td><td>${esc(g.assessment||'—')}</td><td>${esc(g.assessmentType||'Assessment')}</td><td>${esc(g.term)}</td><td>${g.score}%</td><td class="grade">${esc(g.letter||letter(g.score))}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No assessment results have been published yet.</td></tr>'}</tbody></table></div>`}function noticesMini(){return `<div class="activity-list">${db.notices.slice(0,3).map(n=>`<div class="activity-row"><div class="activity-icon">▣</div><div class="activity-text"><b>${esc(n.title)}</b><small>${day(n.date)} · ${esc(n.audience)}</small></div></div>`).join('')||'<div class="empty">No announcements.</div>'}</div>`}
function renderStudents(c){const allowed=current.role==='admin'||current.role==='registrar';c.innerHTML=`${heading('Students & enrollment',allowed?'Review enrollment requests and manage student records.':'Review students enrolled in your classes.',allowed?action('＋ Add student',"openRecord('student')"):action('↓ Export class list','exportRoster()',true))}<div class="page-kpis"><div class="mini-kpi">Active <b>${students().filter(s=>s.status==='Active').length}</b></div><div class="mini-kpi">Awaiting review <b>${students().filter(s=>s.status==='Pending').length}</b></div><div class="mini-kpi">Registration <b>${db.settings.registrationOpen?'Open':'Closed'}</b></div></div><div class="card table-card"><div class="table-toolbar"><div class="filters"><input id="studentSearch" placeholder="Search name or ID…"><select id="studentGrade"><option value="">All grades</option>${[9,10,11,12].map(n=>`<option>Grade ${n}</option>`).join('')}</select><select id="studentStatus"><option value="">All statuses</option><option>Active</option><option>Pending</option><option>Inactive</option></select></div>${action('↓ Export CSV','exportRoster()',true)}</div><div class="table-wrap"><table><thead><tr><th>STUDENT</th><th>STUDENT ID</th><th>GRADE / ROOM</th><th>GUARDIAN</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody id="studentRows"></tbody></table></div></div>`;renderStudentRows();['studentSearch','studentGrade','studentStatus'].forEach(id=>document.getElementById(id).addEventListener('input',renderStudentRows))}
function studentDocsHTML(u){const labels={photo:'Photo',previousSchoolDocument:'Previous school',transcript:'Transcript',paymentProof:'Payment proof'};return `<div class="student-doc-links">${Object.entries(u.documents||{}).map(([k,v])=>v?.fileId?`<a target="_blank" rel="noopener" href="/api/files/${encodeURIComponent(v.fileId)}">${labels[k]||k}</a>`:'').filter(Boolean).join(' · ')}</div>`}function renderStudentRows(){const body=document.getElementById('studentRows');if(!body)return;const q=document.getElementById('studentSearch').value.toLowerCase(),g=document.getElementById('studentGrade').value,st=document.getElementById('studentStatus').value;let list=students().filter(u=>(current.role!=='teacher'||db.classes.some(x=>x.teacher===current.name&&x.grade===u.grade))&&(!q||u.name.toLowerCase().includes(q)||u.id.toLowerCase().includes(q))&&(!g||u.grade===g)&&(!st||u.status===st));body.innerHTML=list.map(u=>`<tr><td class="name">${esc(u.name)}</td><td>${esc(u.id)}</td><td>${esc(u.grade)} · ${esc(u.room||'—')}</td><td>${esc(u.guardian||'—')}</td><td>${badge(u.status)}</td><td>${studentDocsHTML(u)}${u.status==='Pending'&&['admin','registrar'].includes(current.role)?`<button class="button-sm" onclick="approveStudent('${esc(u.id)}')">Approve</button> `:''}${['admin','registrar'].includes(current.role)?`<button class="button-light" onclick="editStudent('${esc(u.id)}')">Edit</button>`:'—'}</td></tr>`).join('')||'<tr><td colspan="6" class="empty">No student records match your filters.</td></tr>'}
function approveStudent(id){if(!['admin','registrar'].includes(current.role))return toast('Only a registrar or administrator can approve enrollment.');const u=students().find(x=>x.id===id);if(!u)return;u.status='Active';u.room=u.room==='Pending'?(db.classes.find(x=>x.grade===u.grade)?.room||'Room assignment pending'):u.room;u.approvedBy=current.name;u.approvedAt=new Date().toISOString();const cl=db.classes.find(x=>x.grade===u.grade);if(cl)cl.students=Number(cl.students||0)+1;save();renderStudentRows();toast(`${u.name} is enrolled and can now sign in with their email.`)}
function renderStaff(c){const list=db.users.filter(u=>['teacher','registrar','admin'].includes(u.role));c.innerHTML=`${heading('Staff directory','Manage teacher, registrar, and administrator accounts.',action('＋ Add staff member',"openRecord('staff')"))}<div class="card table-card"><div class="table-toolbar"><div class="filters"><input id="staffSearch" placeholder="Search staff…"></div>${action('↓ Export CSV','exportStaff()',true)}</div><div class="table-wrap"><table><thead><tr><th>STAFF MEMBER</th><th>EMAIL</th><th>ROLE</th><th>SUBJECT / ASSIGNMENT</th><th>STATUS</th><th></th></tr></thead><tbody id="staffRows">${staffRows(list)}</tbody></table></div></div>`;document.getElementById('staffSearch').oninput=e=>{const q=e.target.value.toLowerCase();document.getElementById('staffRows').innerHTML=staffRows(list.filter(x=>x.name.toLowerCase().includes(q)||x.email.toLowerCase().includes(q)))}}
function staffRows(list){return list.map(u=>`<tr><td class="name">${esc(u.name)}</td><td>${esc(u.email)}</td><td>${esc(roleName[u.role])}</td><td>${esc(u.subject||u.grade||'School administration')}</td><td>${badge(u.status)}</td><td><button class="button-light" onclick="toggleUser('${esc(u.id)}')">${u.status==='Active'?'Deactivate':'Activate'}</button></td></tr>`).join('')}
function renderClasses(c){const mine=current.role==='teacher'?db.classes.filter(x=>x.teacher===current.name):db.classes;const st=students();c.innerHTML=`${heading(current.role==='student'?'My class & timetable':'Classes & timetable',current.role==='student'?`${esc(current.grade||'Grade 10')} · ${esc(current.room||'Room 204')} · Semester 1`:'Organize subject, teacher, room, and class groups.',current.role==='admin'||current.role==='registrar'?action('＋ Add class',"openRecord('class')"):action('↓ Download schedule','exportSchedule()',true))}${current.role==='student'?`<div class="card panel" style="margin-bottom:13px"><h2 style="font:700 12px Manrope;margin:0 0 10px">Class details</h2><div class="page-kpis"><div class="mini-kpi">Grade <b>${esc(current.grade||'Grade 10')}</b></div><div class="mini-kpi">Room <b>${esc(current.room||'Room 204')}</b></div><div class="mini-kpi">Class teacher <b>${esc(mine[0]?.teacher||'Sarah Johnson')}</b></div></div></div>`:''}<div class="grid class-grid">${mine.map(x=>`<article class="card class-card"><h3>${esc(x.name)}</h3><p>${esc(x.teacher)} · ${esc(x.subject)}</p><div class="progress"><span style="width:${Math.min(100,75+Number(x.students||30)%25)}%"></span></div><div class="class-foot"><span>${x.students} students</span><span>${esc(x.room)}</span></div></article>`).join('')}</div><div class="card"><div class="table-toolbar"><h2>${current.role==='student'?'My weekly schedule':'Semester 1 timetable'}</h2><span class="status green">2026–2027</span></div>${current.role==='student'?scheduleForStudent():`<div class="table-wrap"><table><thead><tr><th>CLASS</th><th>GRADE</th><th>SUBJECT</th><th>TEACHER</th><th>ROOM</th><th>STUDENTS</th><th></th></tr></thead><tbody>${mine.map(x=>`<tr><td class="name">${esc(x.name)}</td><td>${esc(x.grade)}</td><td>${esc(x.subject)}</td><td>${esc(x.teacher)}</td><td>${esc(x.room)}</td><td>${x.students}</td><td><button class="button-light" onclick="viewClass('${esc(x.name)}')">Class list</button></td></tr>`).join('')}</tbody></table></div>`}</div>`}
function scheduleForStudent(){const days=['Monday','Tuesday','Wednesday','Thursday','Friday'],sub=['Mathematics','English','Biology','Chemistry','History'];return `<div class="table-wrap"><div class="calendar">${days.map((d,i)=>`<div class="day"><div class="day-head">${d}</div>${[0,1,2,3].map(j=>`<div class="lesson ${j%3===1?'green':j===2?'amber':''}"><b>${['8:00','9:30','11:00','1:00'][j]}</b>${sub[(i+j)%sub.length]}<br>${esc(current.room||'Room 204')}</div>`).join('')}</div>`).join('')}</div></div>`}
function viewClass(name){const cl=db.classes.find(x=>x.name===name);const list=students().filter(s=>s.grade===cl.grade);openModalHtml(name+' · Student list',`${cl.teacher} · ${cl.subject} · ${cl.room}`,`<div class="table-wrap"><table><thead><tr><th>STUDENT</th><th>ID</th><th>GRADE</th><th>ROOM</th><th>MARK</th></tr></thead><tbody>${list.map(s=>`<tr><td class="name">${esc(s.name)}</td><td>${esc(s.id)}</td><td>${esc(s.grade)}</td><td>${esc(s.room||cl.room)}</td><td>${db.grades.filter(g=>g.student===s.name).length?'Recorded':'—'}</td></tr>`).join('')||'<tr><td colspan="5" class="empty">No students assigned to this class yet.</td></tr>'}</tbody></table></div>`)}
function renderRoster(c){const mine=db.classes.filter(x=>current.role!=='teacher'||x.teacher===current.name);c.innerHTML=`${heading('Class roster','View student lists by grade, class, room, and academic record.',action('↓ Export class list','exportRoster()',true))}<div class="card table-card"><div class="table-toolbar"><div class="filters"><select id="rosterClass"><option value="">All classes</option>${mine.map(x=>`<option value="${esc(x.name)}">${esc(x.name)}</option>`).join('')}</select></div></div><div class="table-wrap"><table><thead><tr><th>STUDENT</th><th>STUDENT ID</th><th>CLASS / GRADE</th><th>ROOM</th><th>GUARDIAN</th><th>AVERAGE</th></tr></thead><tbody id="rosterRows"></tbody></table></div></div>`;const draw=()=>{const chosen=document.getElementById('rosterClass').value,grade=mine.find(x=>x.name===chosen)?.grade;const list=students().filter(x=>!grade||x.grade===grade);document.getElementById('rosterRows').innerHTML=list.map(u=>{const gs=db.grades.filter(g=>g.student===u.name),avg=gs.length?Math.round(gs.reduce((a,g)=>a+g.score,0)/gs.length)+'%':'—';return `<tr><td class="name">${esc(u.name)}</td><td>${esc(u.id)}</td><td>${esc(mine.find(x=>x.grade===u.grade)?.name||u.grade)}</td><td>${esc(u.room||'—')}</td><td>${esc(u.guardian||'—')}</td><td>${avg}</td></tr>`}).join('')||'<tr><td colspan="6" class="empty">No students in this class yet.</td></tr>'};document.getElementById('rosterClass').onchange=draw;draw()}
function renderAttendance(c){const today=new Date().toISOString().slice(0,10),mine=db.classes.filter(x=>current.role!=='teacher'||x.teacher===current.name);c.innerHTML=`${heading('Attendance','Daily attendance records, class reports, and follow-up.',action('✓ Mark class attendance',"openAttendance()"))}<div class="page-kpis"><div class="mini-kpi">Present today <b>1,119</b></div><div class="mini-kpi">Absent <b>165</b></div><div class="mini-kpi">School rate <b>87.1%</b></div></div><div class="card table-card"><div class="table-toolbar"><h2>Class attendance · ${day(today)}</h2>${action('↓ Export report','exportAttendance()',true)}</div><div class="table-wrap"><table><thead><tr><th>CLASS</th><th>TEACHER</th><th>PRESENT</th><th>ABSENT</th><th>RATE</th><th>SUBMISSION</th><th></th></tr></thead><tbody>${mine.map(x=>{const a=db.attendance.find(a=>a.className===x.name&&a.date===today);return `<tr><td class="name">${esc(x.name)}</td><td>${esc(x.teacher)}</td><td>${a?`${a.present} / ${x.students}`:'—'}</td><td>${a?a.absent:'—'}</td><td>${a?Math.round(100*a.present/x.students)+'%':'—'}</td><td>${badge(a?'Submitted':'Not submitted')}</td><td>${action('Mark','openAttendance("'+esc(x.name)+'")',true)}</td></tr>`}).join('')}</tbody></table></div></div>`}
function openAttendance(className=''){openModalForm('Record class attendance','Choose today’s attendance counts.',[['Class','className','select',db.classes.filter(x=>current.role!=='teacher'||x.teacher===current.name).map(x=>x.name),className],['Present students','present','number',0],['Absent students','absent','number',0]],v=>{const cl=db.classes.find(x=>x.name===v.className);if(!cl)return toast('Select a class');if(+v.present>cl.students||+v.absent>cl.students||+v.present+ +v.absent>cl.students)return toast(`Class size is ${cl.students}; check the totals.`);db.attendance=db.attendance.filter(a=>!(a.className===cl.name&&a.date===new Date().toISOString().slice(0,10)));db.attendance.push({className:cl.name,present:+v.present,absent:+v.absent,date:new Date().toISOString().slice(0,10),teacher:current.name});save();closeModal();showPage('attendance');toast('Attendance saved')})}
function renderGrades(c){const own=current.role==='student';const list=own?db.grades.filter(g=>g.student===current.name):db.grades.filter(g=>current.role!=='teacher'||db.classes.some(x=>x.teacher===current.name&&x.grade===g.grade));c.innerHTML=`${heading(own?'My grades & transcript':'Grades & transcripts',own?'Review your published results and request an approved transcript.':'Record marks, check transcript details, and approve student transcripts.',!own&&['admin','teacher'].includes(current.role)?action('＋ Record grade',"openRecord('grade')"):own?action('Request transcript','requestTranscript()',true):'')}<div class="page-kpis"><div class="mini-kpi">Semester <b>Semester 1</b></div><div class="mini-kpi">School average <b>${list.length?Math.round(list.reduce((a,g)=>a+g.score,0)/list.length)+'%':'—'}</b></div><div class="mini-kpi">Pass rate <b>92.4%</b></div><div class="mini-kpi">Transcript <b>${own?(current.transcript==='Approved'?'Approved':'Review needed'):'Registrar approval required'}</b></div></div><div class="card table-card"><div class="table-toolbar"><h2>${own?'My assessment results':'Student assessment records'}</h2>${own?action('↓ Download transcript PDF','downloadTranscript()',true):''}</div><div class="table-wrap"><table><thead><tr><th>STUDENT</th><th>GRADE</th><th>SUBJECT</th><th>SEMESTER</th><th>ASSESSMENT</th><th>TYPE</th><th>SCORE</th><th>LETTER</th>${!own?'<th>TRANSCRIPT</th>':''}</tr></thead><tbody>${list.map(g=>`<tr><td class="name">${esc(g.student)}</td><td>${esc(g.grade)}</td><td>${esc(g.subject)}</td><td>${esc(g.term)}</td><td>${esc(g.assessment||'—')}</td><td>${esc(g.assessmentType||'Assessment')}</td><td>${g.score}%</td><td class="grade">${esc(g.letter||letter(g.score))}</td>${!own?`<td>${action('Review & approve',"approveTranscript('"+esc(g.student)+"')",true)}</td>`:''}</tr>`).join('')||`<tr><td colspan="${own?8:9}" class="empty">No published grades yet.</td></tr>`}</tbody></table></div></div>`}
function letter(s){return s>=90?'A':s>=85?'B+':s>=80?'B':s>=75?'C+':s>=70?'C':s>=60?'D':'F'}function approveTranscript(name){if(!['admin','registrar'].includes(current.role))return toast('Only a registrar or administrator can approve transcripts.');const gs=db.grades.filter(x=>x.student===name);if(!gs.length)return toast('No grades to approve.');const u=students().find(x=>x.name===name);openModalHtml('Transcript review',`${name} · ${u?.grade||gs[0].grade} · Semester 1`,`<div class="transcript-head"><h2>Madda Walabu Academy</h2><p>Official student transcript · 2026–2027</p></div><div class="transcript-info"><span>Student</span><b>${esc(name)}</b><span>Student ID</span><b>${esc(u?.id||'—')}</b><span>Grade</span><b>${esc(u?.grade||gs[0].grade)}</b><span>Guardian</span><b>${esc(u?.guardian||'—')}</b></div>${gradeTable(gs)}<div class="approval" style="margin-top:10px">${u?.transcript==='Approved'?'This transcript has already been approved.':'Review each subject and result. Approving allows the student to download a printable PDF transcript.'}</div><div class="modal-actions"><button class="button-light" onclick="closeModal()">Close</button>${u?.transcript==='Approved'?'':`<button class="button-sm" onclick="confirmTranscript('${esc(name)}')">Approve transcript</button>`}</div>`)}function confirmTranscript(name){const u=students().find(x=>x.name===name);if(u){u.transcript='Approved';u.transcriptApprovedBy=current.name;u.transcriptApprovedAt=new Date().toISOString();save()}closeModal();toast('Transcript approved for '+name);if(currentPage==='grades')showPage('grades')}
function requestTranscript(){current.transcriptRequest='Pending';save();toast('Transcript review requested from the registrar.')}
function downloadTranscript(){if(current.transcript!=='Approved'){toast('Transcript must be checked and approved by the registrar first.');return}const gs=db.grades.filter(g=>g.student===current.name);openModalHtml('Transcript · Print / Save as PDF',`Official record for ${current.name}`,`<div id="printTranscript"><div class="transcript-head"><h2>Madda Walabu Academy</h2><p>Official student transcript · Academic year 2026–2027</p></div><div class="transcript-info"><span>Student name</span><b>${esc(current.name)}</b><span>Student ID</span><b>${esc(current.id)}</b><span>Grade</span><b>${esc(current.grade)}</b><span>Room</span><b>${esc(current.room||'—')}</b><span>Guardian</span><b>${esc(current.guardian||'—')}</b><span>Approved by</span><b>${esc(current.transcriptApprovedBy)}</b></div>${gradeTable(gs)}<p class="approval">✓ Checked and approved by registrar · ${day(current.transcriptApprovedAt.slice(0,10))}</p></div><div class="modal-actions"><button class="button-light" onclick="closeModal()">Close</button><button class="button-sm" onclick="window.print()">Print / Save PDF</button></div>`)}
function renderExams(c){if(current.role==='student'){const list=availableExams();c.innerHTML=`${heading('Online exams','Enter an assessment during its scheduled availability. Your answers submit when time runs out.')}<div class="card table-card"><div class="table-toolbar"><h2>Available assessments</h2><span class="status green">School time · ${new Date().toLocaleTimeString([], {hour:'2-digit',minute:'2-digit'})}</span></div>${list.map(examMini).join('')||'<div class="empty">There are no open exams for your grade right now.</div>'}</div><div class="card table-card" style="margin-top:13px"><div class="table-toolbar"><h2>My exam history</h2></div>${examHistory()}</div>`;return}const list=db.exams.filter(x=>current.role!=='teacher'||x.teacher===current.name||current.role==='admin');c.innerHTML=`${heading('Online exams','Create timed assessments, schedule class availability, and review results.',action('＋ Create assessment',"openRecord('exam')"))}<div class="card table-card"><div class="table-toolbar"><h2>Assessments</h2><span class="status green">Timed submissions enabled</span></div><div class="table-wrap"><table><thead><tr><th>ASSESSMENT</th><th>SUBJECT</th><th>GRADE</th><th>DURATION</th><th>STARTS</th><th>ENDS</th><th>QUESTIONS</th><th>SUBMISSIONS</th><th>STATUS</th></tr></thead><tbody>${list.map(x=>`<tr><td class="name">${esc(x.title)}</td><td>${esc(x.subject)}</td><td>${esc(x.grade)}</td><td>${x.minutes} min</td><td>${esc(formatExamDate(x.opens))}</td><td>${esc(formatExamDate(x.closes))}</td><td>${x.questions.length}</td><td>${Object.keys(x.results||{}).length}</td><td>${badge(x.status||'Open')}</td></tr>`).join('')}</tbody></table></div></div><div class="card panel" style="margin-top:13px"><h2 style="font:700 11px Manrope;margin:0 0 7px">Assessment setup</h2><p style="font-size:9px;color:#7e8b83;line-height:1.6;margin:0">Set a start time, select a grade, and add multiple-choice questions. Students sign in with their school email. Each exam has a countdown; submitted answers and scores are saved in this browser.</p></div>`}
function availableExams(){return db.exams.filter(x=>x.grade===current.grade&&x.status!=='Closed'&&new Date(x.opens)<=new Date()&&!x.results?.[current.id])}function formatExamDate(value){if(!value)return 'Not set';const d=new Date(value);return Number.isNaN(d.getTime())?'Not set':d.toLocaleString([], {dateStyle:'medium',timeStyle:'short'})}
function examMini(x){return `<div class="exam-card"><div><h3>${esc(x.title)}</h3><p>${esc(x.subject)} · ${esc(x.grade)} · ${x.questions.length} questions · ${x.minutes} minutes</p><p class="exam-window"><b>Opens:</b> ${esc(formatExamDate(x.opens))} &nbsp; <b>Closes:</b> ${esc(formatExamDate(x.closes))}</p></div>${action('Start exam',"startExam('"+esc(x.id)+"')")}</div>`}function examHistory(){const rows=db.exams.filter(x=>x.results?.[current.id]);return rows.length?`<div class="table-wrap"><table><thead><tr><th>ASSESSMENT</th><th>SUBJECT</th><th>SCORE</th><th>SUBMITTED</th></tr></thead><tbody>${rows.map(x=>`<tr><td class="name">${esc(x.title)}</td><td>${esc(x.subject)}</td><td>${x.results[current.id].score}%</td><td>${day(x.results[current.id].date)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Completed exams will appear here.</div>'}
function startExam(id){const exam=db.exams.find(x=>x.id===id);if(!exam||!availableExams().some(x=>x.id===id))return toast('This assessment is not available.');const end=Date.now()+exam.minutes*60000;const draw=()=>{let sec=Math.max(0,Math.ceil((end-Date.now())/1000)),mm=String(Math.floor(sec/60)).padStart(2,'0'),ss=String(sec%60).padStart(2,'0');const timer=document.getElementById('examTimer');if(timer)timer.textContent=mm+':'+ss;if(sec===0)submitExam(id,true)};openModalHtml(exam.title,`${exam.subject} · ${exam.questions.length} questions`, `<div class="exam-card" style="padding:0 0 12px"><span>Time remaining</span><b class="timer" id="examTimer">${exam.minutes}:00</b></div><form id="examForm">${exam.questions.map((q,i)=>`<div class="question"><h3>${i+1}. ${esc(q.text)}</h3>${q.options.map((o,j)=>`<label class="answer"><input type="radio" name="q${i}" value="${j}" required> ${esc(o)}</label>`).join('')}</div>`).join('')}</form><div class="modal-actions"><button class="button-sm" onclick="submitExam('${esc(id)}',false)">Submit exam</button></div>`);clearInterval(examInterval);draw();examInterval=setInterval(draw,1000)}function submitExam(id,auto){const ex=db.exams.find(x=>x.id===id),form=document.getElementById('examForm');if(!form||!ex)return;const fd=new FormData(form);let correct=0;ex.questions.forEach((q,i)=>{if(Number(fd.get('q'+i))===q.answer)correct++});if(!auto&&[...Array(ex.questions.length).keys()].some(i=>fd.get('q'+i)===null))return toast('Answer every question before submitting.');const score=Math.round(correct/ex.questions.length*100);ex.results[current.id]={score,correct,total:ex.questions.length,date:new Date().toISOString().slice(0,10)};db.grades.push({student:current.name,grade:current.grade,subject:ex.subject,term:'Semester 1',score,letter:letter(score)});save();clearInterval(examInterval);openModalHtml('Exam submitted',auto?'Time was up. Your answers have been submitted automatically.':'Your assessment has been submitted.',`<div class="approval">Result: <b>${score}% (${correct}/${ex.questions.length} correct)</b>. You can review this result in your grades.</div><div class="modal-actions"><button class="button-sm" onclick="closeModal();showPage('exams')">Done</button></div>`)}
function renderFinance(c){const own=current.role==='student',list=own?db.payments.filter(x=>x.studentAuthId===current.authId):db.payments;c.innerHTML=`${heading(own?'My fees & payments':'Fees & finance',own?'Review your academic year registration and payment history.':'Track registration fees, payment records, and balances.',own?action('＋ Pay registration fee',"openRecord('payment')"):['admin','registrar'].includes(current.role)?action('＋ Record payment',"openRecord('payment')"):'')}<div class="grid finance-grid"><div class="card fee-stat"><small>${own?'Registration fee':'Collected this year'}</small><strong>$${own?list.find(p=>p.description.toLowerCase().includes('registration'))?.amount||450:list.filter(p=>p.status==='Paid').reduce((a,p)=>a+Number(p.amount),0).toLocaleString()}</strong><span class="up">${own?'Academic year 2026–2027':'✓ Confirmed payments'}</span></div><div class="card fee-stat"><small>${own?'Payment status':'Awaiting payment'}</small><strong>${own?(list.find(p=>p.description.toLowerCase().includes('registration'))?.status||'Unpaid'):list.filter(p=>p.status==='Pending').length}</strong><span>${own?'Status updates after confirmation':'Pending records'}</span></div><div class="card fee-stat"><small>${own?'Payment method':'Collection rate'}</small><strong style="font-size:15px">${own?(list.find(p=>p.status==='Paid')?.method||'Not selected'):'—'}</strong><span>${own?'Use the school payment instructions':'This academic year'}</span></div></div><div class="card table-card"><div class="table-toolbar"><h2>${own?'My payment history':'Payment records'}</h2>${!own?action('↓ Export report','exportPayments()',true):''}</div><div class="table-wrap"><table><thead><tr>${own?'':'<th>STUDENT</th><th>STUDENT ID</th>'}<th>DESCRIPTION</th><th>AMOUNT</th><th>DATE</th><th>METHOD</th><th>STATUS</th>${!own&&current.role==='admin'?'<th></th>':''}</tr></thead><tbody>${list.map(p=>`<tr>${own?'':`<td class="name">${esc(p.student)}</td><td>${esc((db.users.find(u=>u.name===p.student)?.id)||p.id)}</td>`}<td>${esc(p.description)}</td><td><b>$${Number(p.amount).toFixed(2)}</b></td><td>${day(p.date)}</td><td>${esc(p.method)}</td><td>${badge(p.status)}</td>${!own&&current.role==='admin'?`<td>${p.status==='Pending'?action('Confirm',"confirmPayment('"+esc(p.id)+"','"+esc(p.date)+"')",true):''}</td>`:''}</tr>`).join('')||'<tr><td colspan="7" class="empty">No payments recorded.</td></tr>'}</tbody></table></div></div><p style="font-size:8px;color:#98a29c;margin-top:12px">Online card processing requires a payment provider. This demo records payment requests and confirmations locally; no money is collected.</p>`}
function confirmPayment(id,date){const p=db.payments.find(x=>x.id===id&&x.date===date);if(p){p.status='Paid';p.method='Confirmed by school';save();showPage('finance');toast('Payment marked as paid.')}}
function renderAnnouncements(c){c.innerHTML=`${heading('Announcements','Post important school updates for students, families, and staff.',current.role==='student'? '':action('＋ New announcement',"openRecord('notice')"))}<div class="card panel">${db.notices.map(n=>`<article class="notice"><div style="display:flex;justify-content:space-between;gap:8px"><h3>${esc(n.title)}</h3><span class="status green">${esc(n.audience)}</span></div><p>${esc(n.body)}</p><small>${day(n.date)} · ${esc(n.author)}</small></article>`).join('')||'<div class="empty">No school announcements yet.</div>'}</div>`}
function renderSettings(c){c.innerHTML=`${heading('School settings','Manage annual enrollment, fees, approved payment methods, and the public donation button.',action('Save changes','saveSettings()'))}<div class="card panel" style="max-width:760px"><h2 style="font:700 15px Manrope;margin:0 0 14px">School profile</h2><div class="form-grid-portal"><div class="field full"><label>Website and school name</label><input id="setSchool" value="${esc(db.settings.school)}" required></div><div class="field"><label>Academic year</label><input id="setYear" value="${esc(db.settings.academicYear||'2026–2027')}" required></div><div class="field"><label>Current semester</label><select id="setSemester"><option ${db.settings.semester!=='Semester 2'?'selected':''}>Semester 1</option><option ${db.settings.semester==='Semester 2'?'selected':''}>Semester 2</option></select></div><div class="field"><label>Registration fee</label><input id="setFee" type="number" min="0" step="0.01" value="${esc(String(db.settings.registrationFee??''))}"></div><div class="field"><label>Currency</label><select id="setCurrency"><option ${db.settings.currency==='ETB'?'selected':''}>ETB</option><option ${db.settings.currency==='USD'?'selected':''}>USD</option></select></div><div class="field full"><label>Payment methods · comma separated</label><input id="setPaymentMethods" value="${esc((db.settings.paymentMethods||['Bank transfer','Mobile money','Cash at school']).join(', '))}" required></div></div><hr style="border:0;border-top:1px solid var(--line);margin:19px 0"><h2 style="font:700 15px Manrope;margin:0 0 8px">Annual enrollment</h2><p style="font-size:13px;color:#718079">Turn registration on at the start of a school year. When off, the student enrollment button and form are hidden.</p><label class="setting-toggle"><input id="registrationToggle" type="checkbox" ${db.settings.registrationOpen?'checked':''}> Accept new student registration</label><hr style="border:0;border-top:1px solid var(--line);margin:19px 0"><h2 style="font:700 15px Manrope;margin:0 0 8px">Public donations</h2><p style="font-size:13px;color:#718079">Show or hide a donation button on the public school page. Donations are recorded for school verification.</p><label class="setting-toggle"><input id="donationToggle" type="checkbox" ${db.settings.donationEnabled?'checked':''}> Show donation button on the first page</label><div class="notice" style="margin-top:14px"><h3>Payment processing</h3><p>Payment methods collect a receipt or screenshot for review. Connecting a bank, mobile money, or card provider is needed to move money online automatically.</p></div></div>`}function saveSettings(){db.settings.school=document.getElementById('setSchool').value.trim()||db.settings.school;db.settings.academicYear=document.getElementById('setYear').value.trim();db.settings.semester=document.getElementById('setSemester').value;db.settings.registrationFee=Number(document.getElementById('setFee').value)||0;db.settings.currency=document.getElementById('setCurrency').value;db.settings.paymentMethods=document.getElementById('setPaymentMethods').value.split(',').map(x=>x.trim()).filter(Boolean);db.settings.registrationOpen=document.getElementById('registrationToggle').checked;db.settings.donationEnabled=document.getElementById('donationToggle').checked;save();window.applySchoolBrand?.(db.settings.school);window.applyPublicSettings?.(db.settings);toast('School settings saved.')}function toggleRegistration(v){db.settings.registrationOpen=v;save();toast(v?'Student registration opened.':'Student registration closed.')}function renderProfile(c){c.innerHTML=`${heading('My student profile','Your school identity and family contact information.',action('Edit details',"openRecord('studentEdit')",true))}<div class="card panel" style="max-width:780px"><div style="display:flex;align-items:center;gap:12px;margin-bottom:16px"><span class="user-avatar" style="width:46px;height:46px">${initials(current.name)}</span><div><h2 style="font:700 14px Manrope;margin:0">${esc(current.name)}</h2><small style="color:#829087">${esc(current.id)} · ${esc(current.grade)}</small></div></div><div class="form-grid-portal">${[['School email',current.email],['Student ID',current.id],['Grade',current.grade],['Classroom',current.room],['Date of birth',current.dob||'Not on file'],['Guardian',current.guardian],['Phone',current.phone],['Home address',current.address||'Not on file'],['Emergency contact',current.emergency||current.guardian]].map(([a,b])=>`<div class="field"><label>${a}</label><div style="font-size:10px;padding:8px 0;color:#40554a">${esc(b||'—')}</div></div>`).join('')}</div><p style="font-size:8px;color:#89958e;margin-top:14px">For corrections to your official student information, please contact the registrar.</p></div>`}
function openRecord(type){const admin=['admin','registrar'].includes(current.role);if(type==='student'&&!admin||type==='staff'&&current.role!=='admin'||type==='class'&&!admin||type==='grade'&&!['admin','teacher'].includes(current.role)||type==='exam'&&!['admin','teacher'].includes(current.role)||type==='payment'&&!(admin||current.role==='student')||type==='notice'&&!admin){return toast('Your account does not have access to this action.')}if(type==='student')return window.adminStudentForm?window.adminStudentForm():studentForm();if(type==='studentEdit')return studentEditForm();if(type==='staff')return staffForm();if(type==='class')return classForm();if(type==='grade')return gradeForm();if(type==='exam')return examForm();if(type==='payment')return paymentForm();if(type==='notice')return noticeForm()}
function studentForm(u={}){openModalHtml(u.id?'Edit student record':'Add student record','Complete the student’s first-time enrollment and family details.',`<form id="recordForm" class="form-grid-portal">${field('Full legal name','name','text',u.name,true)}${field('Student email','email','email',u.email,true)}${field('Temporary password','password','text',u.password||'school123',!u.id)}${field('Student ID','id','text',u.id||nextId(),true)}${selectField('Grade','grade',['Grade 9','Grade 10','Grade 11','Grade 12'],u.grade)}${field('Date of birth','dob','date',u.dob||'')}${field('Parent / guardian','guardian','text',u.guardian||'',true)}${field('Guardian phone','phone','tel',u.phone||'')}${field('Classroom / room','room','text',u.room||'Room 204')}${field('Home address','address','text',u.address||'',true)}${field('Emergency contact','emergency','text',u.emergency||'',true)}<div class="field full"><label>Registration payment status</label><select id="f_payment"><option>Pending</option><option>Paid</option><option>Waived</option></select></div></form><div class="modal-actions"><button class="button-light" onclick="closeModal()">Cancel</button><button class="button-sm" onclick="saveStudentForm('${esc(u.id||'')}')">Save student</button></div>`)}function saveStudentForm(editId){const f=document.getElementById('recordForm'),v=formValues(f);if(!v.name||!v.email||!v.guardian)return toast('Name, email, and guardian are required.');const existing=students().find(x=>x.email.toLowerCase()===v.email.toLowerCase()&&x.id!==editId);if(existing)return toast('That email already belongs to a student.');let u=editId?db.users.find(x=>x.id===editId):null;if(!u){u={...v,role:'student',status:'Active',transcript:'Not requested'};db.users.push(u)}else Object.assign(u,v);const pay=document.getElementById('f_payment').value;db.payments.push({student:u.name,id:u.id,description:'Academic year registration',amount:450,status:pay==='Paid'?'Paid':'Pending',date:new Date().toISOString().slice(0,10),method:pay==='Paid'?'Recorded by registrar':'Awaiting payment'});save();closeModal();showPage('students');toast(editId?'Student record updated.':'Student enrolled and record created.')}
function studentEditForm(){studentForm(current)}function editStudent(id){const u=db.users.find(x=>x.id===id||x.authId===id);if(u)studentForm(u)}function nextId(){return 'MWA-'+String(2601+students().length).padStart(4,'0')}function staffForm(){openModalHtml('Add staff member','Create a teacher, registrar, or administrator account.',`<form id="recordForm" class="form-grid-portal">${field('Full name','name','text','',true)}${field('School email','email','email','',true)}${field('Temporary password','password','text','school123',true)}${selectField('Role','role',['teacher','registrar','admin'])}${selectField('Subject / assignment','subject',db.subjects)}${selectField('Assigned grade','grade',['—','Grade 9','Grade 10','Grade 11','Grade 12'])}${field('Phone number','phone','tel','',true)}</form><div class="modal-actions"><button class="button-light" onclick="closeModal()">Cancel</button><button class="button-sm" onclick="saveStaff()">Create account</button></div>`)}function saveStaff(){const v=formValues(document.getElementById('recordForm'));if(!v.name||!v.email||!v.password)return toast('Name, email, and password are required.');if(db.users.some(u=>u.email.toLowerCase()===v.email.toLowerCase()))return toast('An account with that email already exists.');v.id='MWA-'+v.role[0].toUpperCase()+String(db.users.length+100).padStart(3,'0');v.status='Active';v.guardian='—';db.users.push(v);save();closeModal();showPage('staff');toast(`${roleName[v.role]} account created.`)}function toggleUser(id){const u=db.users.find(x=>x.id===id);if(u){u.status=u.status==='Active'?'Inactive':'Active';save();showPage('staff');toast(`${u.name} is ${u.status.toLowerCase()}.`)}}
function classForm(){openModalHtml('Create a class','Assign a grade, subject, teacher, room, and class size.',`<form id="recordForm" class="form-grid-portal">${field('Class name','name','text','e.g. Grade 10C',true)}${selectField('Grade','grade',['Grade 9','Grade 10','Grade 11','Grade 12'])}${selectField('Subject','subject',db.subjects)}${selectField('Teacher','teacher',db.users.filter(x=>x.role==='teacher').map(x=>x.name))}${field('Room','room','text','e.g. Room 205')}${field('Number of students','students','number','30')}</form><div class="modal-actions"><button class="button-light" onclick="closeModal()">Cancel</button><button class="button-sm" onclick="saveClass()">Save class</button></div>`)}function saveClass(){const v=formValues(document.getElementById('recordForm'));if(!v.name||!v.teacher)return toast('Class name and teacher are required.');db.classes.push({...v,students:+v.students||30});save();closeModal();showPage('classes');toast('Class and schedule created.')}
function gradeForm(){openModalHtml('Record assessment result','Publish an assignment, quiz, midterm, final, or other assessment for a student.',`<form id="recordForm" class="form-grid-portal">${selectField('Student','student',students().map(x=>x.name))}${selectField('Grade','grade',['Grade 9','Grade 10','Grade 11','Grade 12'])}${selectField('Subject','subject',db.subjects)}${selectField('Assessment type','assessmentType',['Assignment','Quiz','Midterm test','Final test','Project','Practical','Oral','Online exam','Other'])}${field('Assessment name','assessment','text','e.g. Unit 2 algebra test')}${selectField('Semester','term',['Semester 1','Semester 2'])}${field('Score (%)','score','number','0–100')}</form><div class="modal-actions"><button class="button-light" onclick="closeModal()">Cancel</button><button class="button-sm" onclick="saveGrade()">Publish result</button></div>`)}function saveGrade(){const v=formValues(document.getElementById('recordForm')),score=Number(v.score);if(!v.student||!v.subject||!v.assessmentType||!v.assessment||!Number.isFinite(score)||score<0||score>100)return toast('Complete the assessment details and enter a score from 0 to 100.');db.grades.push({...v,score,letter:letter(score)});save();closeModal();showPage('grades');toast('Student assessment result published.')}function examForm(){openModalHtml('Create online assessment','Add a timed multiple-choice exam for a class.',`<form id="recordForm" class="form-grid-portal">${field('Assessment title','title','text','e.g. Biology · Unit 1',true)}${selectField('Subject','subject',db.subjects)}${selectField('Grade','grade',['Grade 9','Grade 10','Grade 11','Grade 12'])}${field('Time limit (minutes)','minutes','number','30')}${field('Available from','opens','datetime-local',new Date().toISOString().slice(0,16),true)}${field('Available until','closes','datetime-local','',true)}<div class="field full"><label>Question 1</label><input name="q1" placeholder="Write the question" required></div>${['A','B','C','D'].map((x,i)=>`<div class="field"><label>Option ${x}${i===0?' · Correct answer':''}</label><input name="o${i}" required></div>`).join('')}<p class="field full" style="font-size:8px;color:#88948d">This quick form creates one auto-graded multiple-choice question. Add more questions after connecting the full assessment builder.</p></form><div class="modal-actions"><button class="button-light" onclick="closeModal()">Cancel</button><button class="button-sm" onclick="saveExam()">Create assessment</button></div>`)}function saveExam(){const f=document.getElementById('recordForm'),v=formValues(f);if(!v.title||!v.q1||!v.o0||!v.o1||!v.o2||!v.o3)return toast('Complete the question and all four answer options.');if(!v.opens||!v.closes||new Date(v.closes)<=new Date(v.opens))return toast('Choose an end time later than the start time.');const teacher=current.role==='teacher'?current.name:(db.classes.find(x=>x.grade===v.grade&&x.subject===v.subject)?.teacher||current.name);db.exams.push({id:'EX-'+String(Date.now()).slice(-6),title:v.title,subject:v.subject,grade:v.grade,teacher,minutes:Math.max(1,Number(v.minutes)||30),opens:v.opens,closes:v.closes,questions:[{text:v.q1,options:[v.o0,v.o1,v.o2,v.o3],answer:0}],results:{},status:'Open'});save();closeModal();showPage('exams');toast('Timed assessment created. Option A is marked as correct.')}
function paymentForm(){if(current.role==='student'&&window.studentPaymentForm)return window.studentPaymentForm();const own=current.role==='student';openModalHtml(own?'Pay registration fee':'Record a payment',own?'Choose your preferred payment method for the school registration fee.':'Record a payment received by the school.',`<form id="recordForm" class="form-grid-portal">${own?`<div class="field full"><label>Student</label><div style="padding:8px 0">${esc(current.name)} · ${esc(current.id)}</div></div>`:`${selectField('Student','student',students().map(x=>x.name))}${field('Student ID','id','text','MWA-…')}`}${field('Description','description','text','Academic year registration',true)}${field('Amount (USD)','amount','number','450')}${selectField('Payment method','method',['Bank transfer','Mobile money','Cash at school','Card (provider connection required)'])}<div class="field full"><label>Payment reference (optional)</label><input name="reference" placeholder="Bank / mobile transaction reference"></div><p class="field full" style="font-size:8px;color:#88948d">Demo only: this form records a payment request. It does not charge a card or transfer money.</p></form><div class="modal-actions"><button class="button-light" onclick="closeModal()">Cancel</button><button class="button-sm" onclick="savePayment()">${own?'Submit payment request':'Save payment'}</button></div>`)}function savePayment(){const v=formValues(document.getElementById('recordForm')),u=current.role==='student'?current:students().find(x=>x.name===v.student);if(!u||!v.amount||Number(v.amount)<=0)return toast('Select a student and enter a valid amount.');const paid=current.role!=='student'&&confirm('Has the school received and verified this payment? Choose Cancel to keep it pending.');db.payments.push({student:u.name,id:u.id,description:v.description||'School fees',amount:Number(v.amount),status:paid?'Paid':'Pending',date:new Date().toISOString().slice(0,10),method:v.method+(v.reference?' · '+v.reference:'')});save();closeModal();showPage('finance');toast(current.role==='student'?'Payment request recorded. Complete payment with the school office.':'Payment record saved.')}
function noticeForm(){openModalHtml('New announcement','Publish an update to your school community.',`<form id="recordForm" class="form-grid-portal">${field('Announcement title','title','text','',true)}${selectField('Audience','audience',['Everyone','Families','Students','Staff'])}<div class="field full"><label>Message</label><textarea name="body" rows="5" required></textarea></div></form><div class="modal-actions"><button class="button-light" onclick="closeModal()">Cancel</button><button class="button-sm" onclick="saveNotice()">Publish</button></div>`)}function saveNotice(){const v=formValues(document.getElementById('recordForm'));if(!v.title||!v.body)return toast('Enter a title and message.');db.notices.unshift({...v,date:new Date().toISOString().slice(0,10),author:current.name});save();closeModal();showPage('announcements');toast('Announcement published.')}
function field(label,name,type='text',placeholder='',full=false){return `<div class="field ${full?'full':''}"><label>${label}</label><input name="${name}" type="${type}" ${type==='number'?'min="0"':''} ${placeholder!==''?`placeholder="${esc(placeholder)}"`:''} ${type==='text'&&name==='name'||name==='email'?'required':''}></div>`}function selectField(label,name,items,selected=''){return `<div class="field"><label>${label}</label><select name="${name}">${items.map(x=>`<option value="${esc(x)}" ${x===selected?'selected':''}>${esc(x)}</option>`).join('')}</select></div>`}function formValues(form){return Object.fromEntries(new FormData(form).entries())}
function openModalForm(title,sub,fields,onSave){const formFields=fields.map(([label,name,type,opts,full])=>type==='select'?`<div class="field ${full?'full':''}"><label>${label}</label><select name="${name}">${opts.map(x=>`<option ${x===opts[0]?'selected':''}>${esc(x)}</option>`).join('')}</select></div>`:`<div class="field ${full?'full':''}"><label>${label}</label><input name="${name}" type="${type}" ${type==='number'?'min="0" max="1000"':''} placeholder="${esc(String(opts))}" required></div>`).join('');openModalHtml(title,sub,`<form id="recordForm" class="form-grid-portal">${formFields}</form><div class="modal-actions"><button class="button-light" onclick="closeModal()">Cancel</button><button class="button-sm" id="saveFormButton">Save</button></div>`);document.getElementById('saveFormButton').onclick=()=>onSave(formValues(document.getElementById('recordForm')))}function openModalHtml(title,sub,body){document.getElementById('modal').innerHTML=`<h2>${title}</h2><p>${sub}</p>${body}`;document.getElementById('modalBack').classList.add('show')}function closeModal(){document.getElementById('modalBack').classList.remove('show')}document.getElementById('modalBack').onclick=e=>{if(e.target.id==='modalBack')closeModal()};document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
function exportCSV(name,rows){const csv=rows.map(r=>r.map(x=>'"'+String(x??'').replaceAll('"','""')+'"').join(',')).join('\r\n'),blob=new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Spreadsheet downloaded as CSV.')}
function exportRoster(){exportCSV('madda-walabu-students.csv',[['Name','Student ID','Grade','Room','Guardian','Email','Status'],...students().map(u=>[u.name,u.id,u.grade,u.room,u.guardian,u.email,u.status])])}function exportStaff(){exportCSV('madda-walabu-staff.csv',[['Name','Email','Role','Assignment','Status'],...db.users.filter(u=>u.role!=='student').map(u=>[u.name,u.email,u.role,u.subject||u.grade,u.status])])}function exportPayments(){exportCSV('madda-walabu-payments.csv',[['Student','Student ID','Description','Amount','Date','Method','Status'],...db.payments.map(p=>[p.student,p.id,p.description,p.amount,p.date,p.method,p.status])])}function exportAttendance(){exportCSV('madda-walabu-attendance.csv',[['Date','Class','Teacher','Present','Absent'],...db.attendance.map(a=>[a.date,a.className,a.teacher,a.present,a.absent])])}function exportSchedule(){exportCSV('madda-walabu-schedule.csv',[['Class','Grade','Subject','Teacher','Room','Students'],...db.classes.map(x=>[x.name,x.grade,x.subject,x.teacher,x.room,x.students])])}
function toggleChat(){chatOpen=!chatOpen;document.getElementById('chatDrawer').classList.toggle('open',chatOpen);document.getElementById('chatLaunch').classList.toggle('is-hidden',chatOpen)}function renderChat(){if(window.schoolRenderChat)return window.schoolRenderChat();const el=document.getElementById('chatMessages');if(!el)return;el.innerHTML=`<div class="chat-date">SCHOOL OFFICE · LOCAL DEMO</div><div class="bubble staff">Welcome to the school portal. Messages are stored on this device in this demo.<small>School office · 9:15 AM</small></div>${db.chat.map(x=>`<div class="bubble ${x.sender===current?.email?'mine':'staff'}">${esc(x.text)}<small>${esc(x.name)} · ${new Date(x.time).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</small></div>`).join('')}`;el.scrollTop=el.scrollHeight}function sendChat(e){if(window.schoolSendChat)return window.schoolSendChat(e);e.preventDefault();const input=document.getElementById('chatInput'),text=input.value.trim();if(!text)return;db.chat.push({sender:current.email,name:current.name,text,time:new Date().toISOString()});save();input.value='';renderChat()}
document.getElementById('privacyLink').onclick=e=>{e.preventDefault();openModalHtml('Privacy policy','Prototype privacy information','<div class="notice"><h3>Demo data</h3><p>This school portal prototype stores demo records in local browser storage on this device. Do not enter sensitive or real student information. A production portal needs secure hosting, encryption, access controls, retention rules, and an approved privacy notice.</p></div><div class="modal-actions"><button class="button-sm" onclick="closeModal()">Close</button></div>')};document.getElementById('termsLink').onclick=e=>{e.preventDefault();openModalHtml('Terms of use','School portal prototype','<p style="font-size:10px;line-height:1.7;color:#6f7e75">This preview is provided to demonstrate school workflows. Authentication and information are stored in the browser and are not protected for real-world student use. Use only sample data until a secure backend is connected.</p><div class="modal-actions"><button class="button-sm" onclick="closeModal()">Close</button></div>')};
setLanguage(localStorage.getItem('mwa_lang')||'en');
// Bridge points used by the Supabase adapter loaded below app.js.
window.schoolGetData=()=>db;
window.schoolReplaceData=value=>{db=value;localStorage.setItem(KEY,JSON.stringify(db))};
window.schoolGetCurrent=()=>current;
window.schoolSetCurrent=value=>{current=value};
